    font-size: var(--rhino-font-size-xs);
    font-weight: var(--rhino-font-weight-bold);
    justify-content: center;
    letter-spacing: 0.04em;
    min-width: 2.8rem;
}

.rhino-family-identifier__icon {
    height: 2.4rem;
    width: 2.4rem;
}

.rhino-family-identifier__name {
    font-size: var(--rhino-font-size-compact);
    font-weight: var(--rhino-font-weight-semibold);
    line-height: var(--rhino-type-compact-line-height);
    min-width: 0;
    overflow-wrap: anywhere;
}

.rhino-family-identifier--compact {
    min-height: 3.2rem;
    padding:
            var(--rhino-space-1)
            var(--rhino-space-2);
}

.rhino-family-identifier--compact .rhino-family-identifier__name {
    font-size: var(--rhino-font-size-sm);
}

.rhino-family-identifier--muted {
    --rhino-family-accent: var(--rhino-color-steel);

