/* --------------------------------------------------------------------------
 * Rhino icon sizing foundation
 * Source PBI: B-011
 * -------------------------------------------------------------------------- */

.rhino-icon-wrapper {
    align-items: center;
    color: currentColor;
    display: inline-flex;
    flex: 0 0 auto;
    justify-content: center;
    line-height: 0;
    vertical-align: middle;
}

.rhino-icon {
    color: currentColor;
    display: inline-block;
    fill: none;
    flex: 0 0 auto;
    height: 2.4rem;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 1.75;
    vertical-align: middle;
    width: 2.4rem;
}

.rhino-icon-wrapper--default .rhino-icon {
    height: 2.4rem;
    width: 2.4rem;
}

.rhino-icon-wrapper--compact .rhino-icon,
.rhino-icon--compact {
    height: 1.6rem;
    width: 1.6rem;
}

.rhino-icon-wrapper--small .rhino-icon,
.rhino-icon--small {
    height: 2rem;
    width: 2rem;
}

.rhino-icon-wrapper--large .rhino-icon,
.rhino-icon--large {
    height: 3.2rem;
    width: 3.2rem;
}

.rhino-icon--filled {
    fill: currentColor;
    stroke: none;
}

