.rhino-video-card__description {
    color: var(--rhino-color-alloy);
    font-size: var(--rhino-font-size-compact);
    line-height: var(--rhino-type-compact-line-height);
    margin:
            var(--rhino-space-2)
            0
            0;
}

.rhino-video-card__privacy {
    color: var(--rhino-color-alloy);
    font-size: var(--rhino-font-size-sm);
    line-height: 1.538;
    margin:
            var(--rhino-space-3)
            0
            0;
}

.rhino-video-card__player {
